const res = await fetch('https://api.mintly.uk/eiscd-base/v2/eiscd-text.zip', {
  headers: { 'x-api-key': process.env.MINTLY_API_KEY },
})
if (!res.ok) throw new Error((await res.json()).Message)
await writeFile('eiscd-text.zip', Buffer.from(await res.arrayBuffer()))

